import{_ as e,c as t,o as i,ag as o}from"./chunks/framework.CQuhCYrb.js";const p=JSON.parse('{"title":"TAK","description":"","frontmatter":{"title":"TAK"},"headers":[],"relativePath":"general/tak.md","filePath":"general/tak.md","lastUpdated":null}'),n={name:"general/tak.md"};function r(s,a,l,d,u,h){return i(),t("div",null,[...a[0]||(a[0]=[o('<h1 id="tak" tabindex="-1">TAK <a class="header-anchor" href="#tak" aria-label="Permalink to &quot;TAK&quot;">​</a></h1><p>Return to [# ATAK Comprehensive Guide</p><p>Welcome to the comprehensive Team Awareness Kit for Android (ATAK) guide. This guide is tailored for individuals with a military background and is structured to be accessible to users at all levels of familiarity with the platform.</p><ul><li><a href="http://tak.gov/" target="_blank" rel="noreferrer">http://tak.gov/</a></li></ul><h3 id="what-is-atak" tabindex="-1">What is ATAK? <a class="header-anchor" href="#what-is-atak" aria-label="Permalink to &quot;What is ATAK?&quot;">​</a></h3><p>ATAK is a geospatial information and situational awareness application developed by the Air Force Research Laboratory. It facilitates precision targeting, navigation, and data sharing among users.</p><h3 id="getting-started-with-atak" tabindex="-1">Getting Started with ATAK <a class="header-anchor" href="#getting-started-with-atak" aria-label="Permalink to &quot;Getting Started with ATAK&quot;">​</a></h3><h3 id="downloading-atak" tabindex="-1">Downloading ATAK <a class="header-anchor" href="#downloading-atak" aria-label="Permalink to &quot;Downloading ATAK&quot;">​</a></h3><ul><li>Visit the TAK Product Center or CivTAK.org for official downloads.</li></ul><h3 id="setting-up-base-maps-and-elevation-data" tabindex="-1">Setting Up Base Maps and Elevation Data <a class="header-anchor" href="#setting-up-base-maps-and-elevation-data" aria-label="Permalink to &quot;Setting Up Base Maps and Elevation Data&quot;">​</a></h3><ul><li><p>Learn to import maps from sources like Bing Maps, ESRI Clarity, or Google Imagery.</p></li><li><p>Download and integrate elevation data for operational areas.</p></li></ul><h3 id="connecting-to-a-tak-server" tabindex="-1">Connecting to a TAK Server <a class="header-anchor" href="#connecting-to-a-tak-server" aria-label="Permalink to &quot;Connecting to a TAK Server&quot;">​</a></h3><ul><li>Instructions for connecting to existing community servers or setting up your own TAK server for secure communication.</li></ul><h3 id="customizing-and-extending-atak" tabindex="-1">Customizing and Extending ATAK <a class="header-anchor" href="#customizing-and-extending-atak" aria-label="Permalink to &quot;Customizing and Extending ATAK&quot;">​</a></h3><ul><li>Overview of plugins and customizations for specific mission requirements.</li></ul><h3 id="faqs-and-troubleshooting" tabindex="-1">FAQs and Troubleshooting <a class="header-anchor" href="#faqs-and-troubleshooting" aria-label="Permalink to &quot;FAQs and Troubleshooting&quot;">​</a></h3><ul><li>Solutions to common issues faced by new and experienced users alike.</li></ul><h3 id="community-and-support" tabindex="-1">Community and Support <a class="header-anchor" href="#community-and-support" aria-label="Permalink to &quot;Community and Support&quot;">​</a></h3><ul><li>Links to the ATAK Discord, forums, and other resources where users can seek help and share knowledge.</li></ul><p>For detailed instructions, troubleshooting tips, and more advanced topics, refer to the - <a href="/server-guides/">https://www.civtak.org/documentation/ official CivTAK Wiki</a> = <a href="https://www.reddit.com/r/ATAK/wiki/index/" target="_blank" rel="noreferrer">TAK Reddit Page</a></p>',20)])])}const g=e(n,[["render",r]]);export{p as __pageData,g as default};
